struct Uniforms {
  tint : vec3<f32>,
  screenSize : vec2<f32>,
  bands : array<vec4<f32>, 4>,
};
@group(0) @binding(0) var<uniform> u : Uniforms;

@group(0) @binding(1) var trace : texture_2d<f32>;
@group(0) @binding(2) var traceSampler : sampler;

struct ScreenOutput {
  @builtin(position) position : vec4<f32>,
  @location(0) v_uv           : vec2<f32>,
};

const _screenPositions = array<vec2<f32>, 3>(
  vec2<f32>(-1.0, -1.0),
  vec2<f32>( 3.0, -1.0),
  vec2<f32>(-1.0,  3.0),
);
const _screenUVs = array<vec2<f32>, 3>(
  vec2<f32>(0.0, 1.0),
  vec2<f32>(2.0, 1.0),
  vec2<f32>(0.0, -1.0),
);

@vertex fn vertexMain(@builtin(vertex_index) vi : u32) -> ScreenOutput {
  var out : ScreenOutput;
  out.position = vec4<f32>(_screenPositions[vi], 0.0, 1.0);
  out.v_uv     = _screenUVs[vi];
  return out;
}

struct ScreenInput {
  @location(0) v_uv : vec2<f32>,
};

@fragment fn fragmentMain(in : ScreenInput) -> @location(0) vec4<f32> {
  let sz = vec2<f32>(textureDimensions(trace));
  let col = i32(min((in.v_uv.x * sz.x), (sz.x - 1.0)));
  let v = textureLoad(trace, vec2<i32>(col, 0i), 0).r;
  let px = (1.0 / u.screenSize.y);
  let a = clamp(((v + u.bands[1i].x) + px), 0.0, 1.0);
  return vec4<f32>((u.tint.r * a), (u.tint.g * a), (u.tint.b * a), a);
}

