attribute vec2 a_position;

varying vec2 v_uv;

void main() {
  v_uv = vec2(a_position.x * 0.5 + 0.5, 0.5 - a_position.y * 0.5);
  gl_Position = vec4(a_position, 0.0, 1.0);
}

shaders.fragment:
precision highp float;
uniform vec3 tint;
uniform vec2 screenSize;
uniform vec4 bands[4];
varying vec2 v_uv;
uniform sampler2D trace;
uniform highp vec2 _texSize_trace;

void main() {
  vec2 sz = _texSize_trace;
  int col = int(min((v_uv.x * sz.x), (sz.x - 1.0)));
  float v = texture2D(trace, (vec2(col, 0) + 0.5) / _texSize_trace).r;
  float px = (1.0 / screenSize.y);
  float a = clamp(((v + bands[1].x) + px), 0.0, 1.0);
  gl_FragColor = vec4((tint.r * a), (tint.g * a), (tint.b * a), a);
}

shaders.source:
#include <metal_stdlib>
using namespace metal;

struct Uniforms {
  float3 tint;
  float2 screenSize;
  float4 bands[4];
};

struct ScreenOut {
  float4 position [[position]];
  float2 v_uv;
};

vertex ScreenOut vertexMain(uint vid [[vertex_id]]) {
  const float2 pos[3] = { {-1,-1},{3,-1},{-1,3} };
  const float2 uvs[3] = { {0,1},{2,1},{0,-1} };
  ScreenOut out;
  out.position = float4(pos[vid], 0, 1);
  out.v_uv     = uvs[vid];
  return out;
}

fragment float4 fragmentMain(ScreenOut in [[stage_in]], constant Uniforms& u [[buffer(0)]], texture2d<float> trace [[texture(0)]], sampler traceSampler [[sampler(0)]]) {
  float2 sz = float2(trace.get_width(), trace.get_height());
  int col = int(min((in.v_uv.x * sz.x), (sz.x - 1.0)));
  float v = trace.read(uint2(col, 0), 0).r;
  float px = (1.0 / u.screenSize.y);
  float a = clamp(((v + u.bands[1].x) + px), 0.0, 1.0);
  return float4((u.tint.r * a), (u.tint.g * a), (u.tint.b * a), a);
}

shaders.vertex:
#version 300 es

out vec2 v_uv;

void main() {
  const vec2[3] positions = vec2[3](
    vec2(-1.0, -1.0), vec2(3.0, -1.0), vec2(-1.0, 3.0)
  );
  const vec2[3] uvs = vec2[3](
    vec2(0.0, 1.0), vec2(2.0, 1.0), vec2(0.0, -1.0)
  );
  v_uv = uvs[gl_VertexID];
  gl_Position = vec4(positions[gl_VertexID], 0.0, 1.0);
}

shaders.fragment:
#version 300 es
precision highp float;
uniform vec3 tint;
uniform vec2 screenSize;
uniform vec4 bands[4];
in vec2 v_uv;
uniform sampler2D trace;
out vec4 fragColor;

void main() {
  vec2 sz = vec2(textureSize(trace, 0));
  int col = int(min((v_uv.x * sz.x), (sz.x - 1.0)));
  float v = texelFetch(trace, ivec2(col, 0), 0).r;
  float px = (1.0 / screenSize.y);
  float a = clamp(((v + bands[1].x) + px), 0.0, 1.0);
  fragColor = vec4((tint.r * a), (tint.g * a), (tint.b * a), a);
}
